// Costruisce il prompt per Claude CLI
const body = $input.first().json.body;
const event = body.event;
const milestoneName = body.milestone_name || 'Milestone senza nome';
const focusToday = body.focus_today || '';
const nextStep = body.next_step || '';
const timestamp = body.timestamp || new Date().toISOString();

// Pillar summary
const pillars = body.pillars || {};
const pillarLines = Object.entries(pillars).map(([k, v]) => 
  `- ${k}: ${v.pct_complete || 0}% (${v.status || 'N/A'})`
).join('\n');

// Prompt per Claude
const prompt = `Sei l'Archivista Creativo di TITANIUM_OS.

Evento: ${event === 'milestone_completed' ? '✅ MILESTONE COMPLETATA' : '🎯 NUOVA MILESTONE'}
Milestone: ${milestoneName}
Data: ${timestamp.slice(0,10)}
Focus oggi: ${focusToday}
Prossimo step: ${nextStep}

Stato pillar:
${pillarLines}

Scrivi uno storytelling in italiano per questa milestone. Formato:

# ${milestoneName}
**Data**: ${timestamp.slice(0,10)}
**Tipo**: ${event}

## Il Momento
[2-3 frasi che raccontano questo momento del progetto in modo visivo e concreto]

## Il Significato
[1-2 frasi sul perché questo step conta nel quadro generale]

## LinkedIn (max 3 righe)
[Post professionale e diretto]

## Podcast (traccia)
[3 bullet point narrativi per audio]

Solo il testo, nessun commento aggiuntivo.`;

return [{ json: { prompt, milestoneName, event, timestamp } }];

// Salva il .md in CONTENT_ENGINE/produzione_contenuti/
const fs = require('fs');
const path = require('path');

const storytelling = $input.first().json.stdout || 'Errore: nessun output da Claude';
const milestone = $('build-prompt').first().json.milestoneName;
const timestamp = $('build-prompt').first().json.timestamp;

// Nome file sicuro
const safeName = milestone.replace(/[^a-zA-Z0-9_\-àèìòù]/g, '_').slice(0, 60);
const dateStr = timestamp.slice(0, 10);
const filename = `${dateStr}_${safeName}.md`;
const outputDir = 'C:/Users/Matteo/Desktop/CONTENT_ENGINE/produzione_contenuti';
const filepath = path.join(outputDir, filename);

// Salva file
fs.mkdirSync(outputDir, { recursive: true });
fs.writeFileSync(filepath, storytelling, 'utf8');

return [{ json: { filepath, filename, storytelling, milestone } }];
